node -e "
const PDFDocument = require('pdfkit');
const fs = require('fs');

const doc = new PDFDocument({ margin: 50 });
const outPath = '/workspace/testbed/docs/maya_chen_customer_report.pdf';
doc.pipe(fs.createWriteStream(outPath));

// --- Title ---
doc.fontSize(20).font('Helvetica-Bold').text('Customer Activity Report', { align: 'center' });
doc.moveDown(1);

// --- Customer Info ---
doc.fontSize(16).font('Helvetica-Bold').text('Maya Chen');
doc.moveDown(0.3);
doc.fontSize(10).font('Helvetica')
   .text('Email: maya.chen@example.com')
   .text('Loyalty Tier: Gold')
   .text('Store Credit: \$0');
doc.moveDown(1);

// --- Orders ---
const orders = [
  { id: 'ORD-6C71B1', date: '2026-09-02', status: 'Cancelled', total: '\$79',  items: 'Anker Portable Bluetooth Speaker' },
  { id: 'ORD-5B048F', date: '2026-09-02', status: 'Confirmed', total: '\$108', items: 'Anker Portable Bluetooth Speaker, LogiTech Wireless Mouse M310' },
  { id: 'ORD-12AAA3', date: '2026-09-02', status: 'Cancelled', total: '\$39',  items: 'Wireless Ergonomic Mouse' },
  { id: 'ORD-542FDA', date: '2026-09-02', status: 'Confirmed', total: '\$68',  items: 'OXO SoftWorks 3-Piece Mixing Bowl Set, ThermoPro Digital Meat Thermometer' },
  { id: 'ORD-D7E869', date: '2026-09-02', status: 'Confirmed', total: '\$71',  items: 'LogiTech Wireless Mouse M310, OXO SoftWorks 3-Piece Mixing Bowl Set' },
  { id: 'ORD-C31654', date: '2026-09-02', status: 'Confirmed', total: '\$29',  items: 'Wireless Mouse' },
  { id: 'ORD-CCC96C', date: '2026-09-02', status: 'Confirmed', total: '\$201', items: 'LogiTech Wireless Mouse M310, OXO SoftWorks 3-Piece Mixing Bowl Set, Aurora Smart Desk Lamp Pro' },
];

doc.fontSize(14).font('Helvetica-Bold').text('Orders');
doc.moveDown(0.5);

// Table header
const colX = { order: 50, date: 150, status: 240, total: 330, items: 390 };
doc.fontSize(9).font('Helvetica-Bold');
doc.text('Order ID',  colX.order,  doc.y, { continued: false });
const headerY = doc.y - doc.currentLineHeight();
doc.text('Date',      colX.date,   headerY, { continued: false });
doc.text('Status',    colX.status, headerY, { continued: false });
doc.text('Total',     colX.total,  headerY, { continued: false });
doc.text('Items',     colX.items,  headerY, { continued: false });
doc.moveDown(0.3);

// Divider
const lineY = doc.y;
doc.moveTo(colX.order, lineY).lineTo(560, lineY).stroke();
doc.moveDown(0.3);

// Table rows
doc.font('Helvetica').fontSize(9);
orders.forEach((o) => {
  const rowY = doc.y;
  doc.text(o.id,     colX.order,  rowY);
  doc.text(o.date,   colX.date,   rowY);

  // Color-code status
  const statusColor = o.status === 'Confirmed' ? 'green' : 'red';
  doc.fillColor(statusColor).text(o.status, colX.status, rowY);
  doc.fillColor('black');

  doc.text(o.total,  colX.total,  rowY);
  doc.text(o.items,  colX.items,  rowY, { width: 170 });
  doc.moveDown(0.6);
});

// --- Summary ---
doc.moveDown(0.5);
doc.fontSize(11).font('Helvetica-Bold').text('Summary');
doc.moveDown(0.3);
doc.fontSize(10).font('Helvetica');
doc.text('Total Orders: 7');
doc.text('Confirmed: 5  |  Cancelled: 2');
doc.text('Combined Total: \$595');

doc.end();
console.log('PDF created at: ' + outPath);
"

